/* Number of files per tree level; the number of blocks a tree of the given
 * depth can hold is TREEDIRSIZE^depth. */
static int tree_levels(off_t size) {
	int levels = 1;
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t capacity = TREEDIRSIZE;

	while (blocks > capacity) {
		levels++;
		capacity *= TREEDIRSIZE;
	}
	return levels;
}
