/**
 * Trim a range of a treefiles export: delete the files for blocks that are
 * fully covered by the range, and zero out the blocks that are only
 * partially covered.
 *
 * @param name the name of the root directory of the tree
 * @param size the total size of the export
 * @param pos the start of the range to trim
 * @param len the length of the range to trim
 * @return 0 on success, -1 on failure
 */
int trim_treefiles(char *name, off_t size, off_t pos, off_t len) {
	static const char zeroes[TREEPAGESIZE];
	int levels = tree_levels(size);
	char path[strlen(name) + 5 * levels + 1];
	off_t end = pos + len;

	while (pos < end) {
		off_t ppos;
		off_t chunk = TREEPAGESIZE - (pos % TREEPAGESIZE);

		if (chunk > end - pos)
			chunk = end - pos;
		strcpy(path, name);
		construct_path(path, sizeof(path), size, pos, &ppos);
		if (ppos == 0 && chunk == TREEPAGESIZE) {
			/* The block is fully covered; drop the file */
			delete_treefile(name, size, pos);
		} else {
			int fd = open(path, O_RDWR);
			if (fd >= 0) {
				if (pwrite(fd, zeroes, chunk, ppos) != chunk) {
					close(fd);
					return -1;
				}
				close(fd);
			} else if (errno != ENOENT) {
				return -1;
			}
		}
		pos += chunk;
	}
	return 0;
}
```

