/*
 * Tree files support
 *
 * An export using the treefiles option stores its data in a tree of
 * directories and files rather than in a single file. The exportname is
 * the root directory of the tree. Every directory in the tree holds at
 * most TREEDIRSIZE entries, which are either subdirectories or data files,
 * and every data file holds at most TREEPAGESIZE bytes of export data.
 *
 * The tree is sized so that the whole export fits: its number of levels is
 * the smallest number which allows at least ceil(size / TREEPAGESIZE) data
 * files to be addressed. Every byte of export data thus maps to exactly one
 * file and one offset within that file.
 *
 * Files and the directories containing them are created on demand when data
 * is first written, and files are deleted again when the block they hold is
 * trimmed or zeroed. Parts of the export for which no file exists read back
 * as all zeroes.
 */

#include "lfs.h"
#include "config.h"
#include "nbd-debug.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <cliserv.h>
#include <treefiles.h>

/* Size of a buffer which can hold the path of any file in the tree rooted
 * at a name of the given length */
#define TREEPATHLEN(namelen, size) ((namelen) + 5 * tree_levels(size) + 1)

/* Maximum number of blocks a tree of the given number of levels can hold;
 * each level adds a factor TREEDIRSIZE to the capacity */
static off_t tree_capacity(int levels) {
	off_t capacity = 1;

	while (levels-- > 0) {
		capacity *= TREEDIRSIZE;
	}
	return capacity;
}

/* The number of levels needed for the tree to hold an export of the given
 * size, i.e. the smallest number of levels for which the tree can hold
 * ceil(size / TREEPAGESIZE) files */
static int tree_levels(off_t size) {
	int levels = 1;
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;

	while (blocks > tree_capacity(levels)) {
		levels++;
	}
	return levels;
}

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block = pos / TREEPAGESIZE;
	int levels = tree_levels(size);
	int used = strlen(name);
	int i;

	assert(pos >= 0);
	assert(pos < size);
	assert(used < lenmax);

	if (ppos) {
		*ppos = pos % TREEPAGESIZE;
	}

	for (i = levels - 1; i >= 0; i--) {
		int entry = (block / tree_capacity(i)) % TREEDIRSIZE;

		used += snprintf(name + used, lenmax - used, "/%04d", entry);
		if (used >= lenmax) {
			msg(LOG_ERR, "treefiles: could not construct path, buffer of %d bytes too small", lenmax);
			abort();
		}
	}
}

void delete_treefile(char *name, off_t size, off_t pos) {
	char path[TREEPATHLEN(strlen(name), size)];

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	if (unlink(path) < 0 && errno != ENOENT) {
		msg(LOG_ERR, "treefiles: could not delete file %s: %s", path, strerror(errno));
	}
}

void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			if (mkdir(path, 0700) < 0 && errno != EEXIST) {
				msg(LOG_ERR, "treefiles: could not create directory %s: %s", path, strerror(errno));
			}
			*p = '/';
		}
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST) {
		msg(LOG_ERR, "treefiles: could not create directory %s: %s", path, strerror(errno));
	}
}

int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[TREEPATHLEN(strlen(name), size)];
	char *sep;
	int fd;

	pthread_mutex_lock(mutex);
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	if ((mode & O_CREAT) && (sep = strrchr(path, '/')) != NULL) {
		*sep = '\0';
		mkdir_path(path);
		*sep = '/';
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);
	return fd;
}

int trim_treefiles(char *name, off_t size, off_t pos, off_t len) {
	static const char zeroes[TREEPAGESIZE];
	char path[TREEPATHLEN(strlen(name), size)];
	off_t end = pos + len;

	while (pos < end) {
		off_t ppos;
		off_t chunk = TREEPAGESIZE - (pos % TREEPAGESIZE);

		if (chunk > end - pos) {
			chunk = end - pos;
		}
		strcpy(path, name);
		construct_path(path, sizeof(path), size, pos, &ppos);
		if (ppos == 0 && chunk == TREEPAGESIZE) {
			/* The block is fully covered by the range; drop it */
			if (unlink(path) < 0 && errno != ENOENT) {
				msg(LOG_ERR, "treefiles: could not delete file %s: %s", path, strerror(errno));
				return -1;
			}
		} else {
			/* Zero out the part of the block covered by the
			 * range; if the file doesn't exist, the range reads
			 * back as zeroes anyway */
			int fd = open(path, O_RDWR);

			if (fd >= 0) {
				if (pwrite(fd, zeroes, chunk, ppos) != chunk) {
					close(fd);
					return -1;
				}
				close(fd);
			} else if (errno != ENOENT) {
				return -1;
			}
		}
		pos += chunk;
	}
	return 0;
}

