/**
 * Read an amount of bytes at a given offset from the treefiles tree. The
 * read is limited to the file containing the offset; if that file does not
 * exist, zeroes are returned.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes read (equal to len), or -1 in case of an
 * error.
 **/
static ssize_t rawtreeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	char name[strlen(client->exportname) + 1];
	off_t ppos = a % TREEPAGESIZE;
	size_t chunk = TREEPAGESIZE - ppos;
	int fd;
	ssize_t ret;

	if (len > chunk) {
		len = chunk;
	}
	strcpy(name, client->exportname);
	fd = open_treefile(name, O_RDONLY, client->exportsize, a, &client->tree_lock);
	if (fd < 0) {
		if (errno == ENOENT) {
			/* The block was never written; it reads back as
			 * zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	ret = pread(fd, buf, len, ppos);
	close(fd);
	if (ret < 0) {
		return -1;
	}
	if ((size_t)ret < len) {
		/* Reading beyond the end of the last (partial) block; the
		 * remainder reads back as zeroes */
		memset(buf + ret, 0, len - ret);
	}
	return len;
}
