#include <errno.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include "nbd.h"

#define OPTS_MAGIC 0x49484156454F5054LL
#define INIT_PASSWD "NBDMAGIC"

static uint64_t ntohll(uint64_t a) {
	uint32_t lo = a & 0xffffffff, hi = a >> 32;
	lo = ntohl(lo); hi = ntohl(hi);
	return ((uint64_t)lo << 32) | hi;
}
#define htonll ntohll

static void rdall(int fd, void *b, size_t n) {
	size_t off = 0;
	while (off < n) {
		ssize_t r = read(fd, (char*)b + off, n - off);
		if (r <= 0) { fprintf(stderr, "rdall: short/eof at %zu/%zu: %s\n", off, n, strerror(errno)); exit(3); }
		off += r;
	}
}
static void wrall(int fd, const void *b, size_t n) {
	size_t off = 0;
	while (off < n) {
		ssize_t w = write(fd, (const char*)b + off, n - off);
		if (w <= 0) { fprintf(stderr, "wrall: %s\n", strerror(errno)); exit(3); }
		off += w;
	}
}

static int connect_host(const char *host, int port) {
	struct addrinfo hints, *res;
	char portstr[16];
	snprintf(portstr, sizeof(portstr), "%d", port);
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	if (getaddrinfo(host, portstr, &hints, &res) != 0) { fprintf(stderr, "getaddrinfo failed\n"); exit(3); }
	int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
	if (fd < 0 || connect(fd, res->ai_addr, res->ai_addrlen) < 0) { fprintf(stderr, "connect: %s\n", strerror(errno)); exit(3); }
	freeaddrinfo(res);
	return fd;
}

/* negotiate with export name, return size */
static uint64_t negotiate(int fd, const char *name, uint16_t *eflags) {
	char buf[256];
	uint64_t m, size;
	uint16_t hflags, tflags;
	uint32_t cflags = 0, opt, len;

	rdall(fd, buf, strlen(INIT_PASSWD));
	if (strncmp(buf, INIT_PASSWD, strlen(INIT_PASSWD))) { fprintf(stderr, "bad init passwd\n"); exit(3); }
	rdall(fd, &m, 8);
	if (ntohll(m) != OPTS_MAGIC) { fprintf(stderr, "bad opts magic\n"); exit(3); }
	rdall(fd, &hflags, 2);
	hflags = ntohs(hflags);
	if (hflags & NBD_FLAG_FIXED_NEWSTYLE) cflags |= NBD_FLAG_C_FIXED_NEWSTYLE;
	cflags = htonl(cflags);
	wrall(fd, &cflags, 4);
	m = htonll(OPTS_MAGIC); wrall(fd, &m, 8);
	opt = htonl(NBD_OPT_EXPORT_NAME); wrall(fd, &opt, 4);
	len = htonl((uint32_t)strlen(name)); wrall(fd, &len, 4);
	wrall(fd, name, strlen(name));
	rdall(fd, &size, 8); size = ntohll(size);
	rdall(fd, &tflags, 2); *eflags = ntohs(tflags);
	rdall(fd, buf, 124);
	return size;
}

static void do_req(int fd, uint32_t cmd, uint64_t from, uint32_t len, void *data) {
	struct nbd_request req;
	struct nbd_reply rep;
	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(cmd);
	req.cookie = htonll(from);
	req.from = htonll(from);
	req.len = htonl(len);
	wrall(fd, &req, sizeof(req));
	if (cmd == NBD_CMD_WRITE) wrall(fd, data, len);
	rdall(fd, &rep, sizeof(rep));
	if (ntohl(rep.magic) != NBD_REPLY_MAGIC) { fprintf(stderr, "bad reply magic\n"); exit(4); }
	if (ntohl(rep.error)) { fprintf(stderr, "server error %u\n", ntohl(rep.error)); exit(4); }
	if (ntohll(rep.cookie) != from) { fprintf(stderr, "cookie mismatch\n"); exit(4); }
	if (cmd == NBD_CMD_READ) rdall(fd, data, len);
}

int main(int argc, char **argv) {
	if (argc < 5) { fprintf(stderr, "usage: %s wr|rd|rdz|sz host port export [off len fill]\n", argv[0]); return 2; }
	const char *op = argv[1], *host = argv[2], *exp = argv[4];
	int port = atoi(argv[3]);
	int fd = connect_host(host, port);
	uint16_t eflags;
	uint64_t size = negotiate(fd, exp, &eflags);

	if (!strcmp(op, "sz")) { printf("%llu\n", (unsigned long long)size); close(fd); return 0; }

	uint64_t off = strtoull(argv[5], NULL, 0);
	uint32_t len = (uint32_t)strtoul(argv[6], NULL, 0);

	if (!strcmp(op, "wr") || !strcmp(op, "rd")) {
		unsigned char fill = (unsigned char)strtoul(argv[7], NULL, 0);
		char *buf = malloc(len);
		if (!strcmp(op, "wr")) {
			memset(buf, fill, len);
			do_req(fd, NBD_CMD_WRITE, off, len, buf);
			printf("WROTE ok: off=%llu len=%u fill=0x%02x\n", (unsigned long long)off, len, fill);
		} else {
			do_req(fd, NBD_CMD_READ, off, len, buf);
			for (uint32_t i = 0; i < len; i++) {
				if ((unsigned char)buf[i] != fill) {
					fprintf(stderr, "MISMATCH at off+%u: got 0x%02x want 0x%02x\n", i, buf[i], fill);
					return 1;
				}
			}
			printf("READ ok: off=%llu len=%u fill=0x%02x\n", (unsigned long long)off, len, fill);
		}
		free(buf);
	} else if (!strcmp(op, "rdz")) {
		char *buf = malloc(len);
		do_req(fd, NBD_CMD_READ, off, len, buf);
		for (uint32_t i = 0; i < len; i++) {
			if (buf[i] != 0) { fprintf(stderr, "NONZERO at off+%u: 0x%02x\n", i, (unsigned char)buf[i]); return 1; }
		}
		printf("READZERO ok: off=%llu len=%u\n", (unsigned long long)off, len);
		free(buf);
	} else {
		fprintf(stderr, "unknown op %s\n", op); return 2;
	}

	struct nbd_request req = { htonl(NBD_REQUEST_MAGIC), htonl(NBD_CMD_DISC), htonll(0), htonll(0), 0 };
	wrall(fd, &req, sizeof(req));
	close(fd);
	return 0;
}

